]+)"#) { var cleaned = cleanCapturedValue(named) if let range = cleaned.range(of: #"(?i)\s+(?:for|in)\s+\d+\s+(?:seconds?|minutes?|hours?|days?) "#, options: .regularExpression) { cleaned = String(cleaned[..<range.lowerBound]).trimmingCharacters(in: .whitespacesAndNewlines) } if !cleaned.isEmpty { return cleaned } } return fallback } private static func extractTriggerCancelIdentifier(from prompt: String) -> String { if let uuid = firstUUID(in: prompt) { return uuid } if let named = firstCapture(in: prompt, pattern: #"(?i) (?:named|called)\s+([^.!?
]+)"#) { return cleanCapturedValue(named) } if let trigger = firstCapture(in: prompt, pattern: #"(?i) cancel\s+(?:the\s+)?(?:trigger|scheduled run|agent run)\s+([^.!?
]+)"#) { return cleanCapturedValue(trigger) } return "" } private static func extractTriggerTitle(from prompt: String) -> String { let lower = normalized(prompt) if lower.contains("reminder") { return "Reminder summary" } if lower.contains("digest") { return "Scheduled digest" } return "Scheduled agent run" } private static func isPersonalProfileRecallIntent(_ text: String) -> Bool { IntentRouter.isPersonalProfileRecallIntent(text) } private static func isLatestOutlookReadIntent(_ text: String) -> Bool { containsAny(text, ["latest email", "last email", "read latest", "open latest", "open email", "latest outlook email", "last outlook email", "read my latest email", "read outlook message"]) }

